// migrateDb runs the provided goose command - usually the 'up' command to apply
// migrations.
func migrateDb(
	command string,
	arguments []string,
	logger zap.Logger,
) error {
	// get non-root database connection string
	dsn, err := database.GetDsn(false)
	if err != nil {
		returnErr("failed to populate DB DSN from environment", err)
	}

	// configure goose driver
	db, err := goose.OpenDBWithDriver("postgres", dsn)
	if err != nil {
		returnErr("goose failed to open DB", err)
	}
	defer func() {
		if err := db.Close(); err != nil {
			returnErr("goose failed to close DB", err)
		}
	}()

	// configure gorm DB
	gormdb, err := gorm.Open(postgres.Open(dsn), &gorm.Config{
		Logger: &database.ZapLogger{Logger: &logger},
		NowFunc: func() time.Time {
			utc, _ := time.LoadLocation("UTC")
			return time.Now().In(utc).Truncate(time.Microsecond)
		},
	})
	if err != nil {
		returnErr("could not create gorm db object", err)
	}

	// run migrations
	ctx := context.WithValue(context.TODO(), "gormdb", gormdb)
	goose.SetTableName("threeport_goose_db_version")
	// a plain 'up' applies the pending migrations so that a failed one is
	// rolled back rather than left part way; any other goose command runs as is,
	// under the migration lock when it changes the schema
	if command == "up" && len(arguments) == 0 {
		if err := upWithRollback(ctx, db, logger); err != nil {
			returnErr("failed to migrate database schema", err)
		}
	} else if err := runGooseCommand(ctx, db, logger, command, arguments); err != nil {
		returnErr(fmt.Sprintf("goose %s command failed", command), err)
	}

	logger.Info("database schema successfully migrated")

	return nil
}

// upWithRollback applies every pending migration.  A migration that fails is
// rolled back along with the ones applied before it in the same run, and the
// failure is recorded so the migrator does not try again until an operator
// clears it.
func upWithRollback(ctx context.Context, db *sql.DB, logger zap.Logger) error {
	steps, err := migrator.RegisteredGooseSteps(db)
	if err != nil {
		return err
	}
	record, err := migrator.NewTableFailureRecord(ctx, db, "threeport_goose_db_version_failure")
	if err != nil {
		return err
	}
	lock, err := migrationLock(ctx, db)
	if err != nil {
		return err
	}

	opts := migrator.Options{
		Lock: lock,
		Logf: func(format string, args ...interface{}) {
			logger.Info(fmt.Sprintf(format, args...))
		},
	}
	backup, err := databaseBackup()
	if err != nil {
		return err
	}
	opts.Backup = backup

	return migrator.Up(ctx, steps, record, opts)
}

// runGooseCommand runs a goose command other than a plain 'up'.  One that
// changes the schema holds the migration lock while it runs, so an operator
// rolling back by hand cannot run beside an API server pod's migrator applying
// migrations.  It gets no backup or rollback, which a plain 'up' alone has.
func runGooseCommand(ctx context.Context, db *sql.DB, logger zap.Logger, command string, arguments []string) error {
	run := func() error {
		return goose.RunContext(ctx, command, db, ".", arguments...)
	}
	if command == "status" {
		return run()
	}

	lock, err := migrationLock(ctx, db)
	if err != nil {
		return err
	}

	return migrator.WithLock(ctx, lock, func(format string, args ...interface{}) {
		logger.Info(fmt.Sprintf(format, args...))
	}, run)
}

// migrationLock returns the lock every migrator of this database takes before
// changing its schema.  The API server's pods start together, and only one may
// migrate at a time; a pod is named by its host name, which an init container
// restarted in the same pod keeps.
func migrationLock(ctx context.Context, db *sql.DB) (*migrator.TableLock, error) {
	holder, err := os.Hostname()
	if err != nil {
		return nil, err
	}

	return migrator.NewTableLock(ctx, db, "threeport_goose_db_version_lock", holder)
}

// databaseBackup returns a backup of the database into the location the install
// configured, taken as the root user since CockroachDB lets only an admin back
// up to cloud storage with the node's own identity.  It returns nil when the
// install configured no backups.
func databaseBackup() (migrator.BackupFunc, error) {
	uri, err := os.ReadFile(filepath.Join(installer.DbBackupConfigLocation, installer.DbBackupURIFilename))
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the database backup location: %w", err)
	}

	dsn, err := database.GetDsn(true)
	if err != nil {
		return nil, fmt.Errorf("failed to get the root database connection string: %w", err)
	}
	rootDb, err := sql.Open("postgres", dsn)
	if err != nil {
		return nil, fmt.Errorf("failed to open a root database connection: %w", err)
	}

	return migrator.CockroachBackup(rootDb, database.ThreeportDatabaseName, strings.TrimSpace(string(uri))), nil
}

// initializeDb creates the database and user using root database user.
func initializeDb(logger zap.Logger) error {
	dsn, err := database.GetDsn(true)
	if err != nil {
		return fmt.Errorf("failed to get data source string: %w", err)
	}

	// at deployment time, this is the first database connection made so we
	// retry the connection for 5 min before returning an error
	var connAttemptsMax = 30
	var connAttemptIntervalSeconds = 10
	var connAttempts = 0
	var gormDb *gorm.DB
	var dbConnErr error
	for connAttempts < connAttemptsMax {
		db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{
			Logger: &database.ZapLogger{Logger: &logger},
			NowFunc: func() time.Time {
				utc, _ := time.LoadLocation("UTC")
				return time.Now().In(utc).Truncate(time.Microsecond)
			},
		})
		if err != nil {
			logger.Info(fmt.Sprintf(
				"failed to make DB connection, retrying in %d seconds",
				connAttemptIntervalSeconds,
			))
			dbConnErr = err
		} else {
			gormDb = db
			break
		}
		connAttempts++
		time.Sleep(time.Second * time.Duration(connAttemptIntervalSeconds))
	}
	if gormDb == nil {
		return fmt.Errorf("timed out after 5 mim attempting to make database connection: %w", dbConnErr)
	}

	// execute SQL init script
	sqlFile := filepath.Join(installer.DbInitLocation, installer.DbInitFilename)
	sqlScript, err := ioutil.ReadFile(sqlFile)
	if err != nil {
		returnErr("failed to read SQL init script", err)
	}
	if err := gormDb.Exec(string(sqlScript)).Error; err != nil {
		returnErr("failed to execute SQL init script", err)
	}

	if err := createBackupSchedule(gormDb, logger); err != nil {
		returnErr("failed to create database backup schedule", err)
	}

	logger.Info("database successfully initialized")

	return nil
}

// createBackupSchedule creates the database backup schedule when the install
// provides one.  It runs on its own rather than in the init script because
// CockroachDB checks the backup target exists when the schedule is created,
// which it does not until the init script's transaction commits.  The check
// also reads the backup destination, so it is retried while access to it,
// such as a newly granted Workload Identity binding, takes effect.
func createBackupSchedule(gormDb *gorm.DB, logger zap.Logger) error {
	scheduleFile := filepath.Join(installer.DbInitLocation, installer.DbBackupScheduleFilename)
	scheduleScript, err := os.ReadFile(scheduleFile)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("failed to read database backup schedule: %w", err)
	}

	if err := util.Retry(30, 10, func() error {
		err := gormDb.Exec(string(scheduleScript)).Error
		if err != nil {
			logger.Info("failed to create database backup schedule, retrying in 10 seconds", zap.Error(err))
		}
		return err
	}); err != nil {
		return err
	}
	logger.Info("database backup schedule in place")

	return nil
}

